using System;
using System.Collections.Generic;
using System.Text;
using UnityEngine;

/// <summary>
/// PHASE 5.4 — exterior detailing and decoration. Adds architectural details, openings, and decorative
/// elements to buildings generated by BuildingSystem. Architectural details are also written back to
/// BuildingSystem.Building.exterior.architecturalDetails so BuildingValidator can check them.
/// </summary>
public static class ExteriorDetailSystem
{
    /// <summary>An exterior detail instance placed on a building (world space).</summary>
    public class ExteriorDetail
    {
        public string detailId;         // ArchitecturalKit piece ID, "door"/"window", or generated feature ID
        public Vector3 position;        // World position of the detail
        public Quaternion rotation;     // Orientation of the detail
        public Vector3 scale;           // Scale of the detail
        public bool isArchitectural;    // True if this is an architectural piece from ArchitecturalKit
        public string featureType;      // "door"/"window" or decorative type: "flowerPot", "lantern", ...
    }

    /// <summary>Exterior details assigned to one building.</summary>
    public class DetailedBuilding
    {
        public int buildingId;               // index into BuildingSystem.Buildings
        public List<ExteriorDetail> details; // all exterior details for this building
    }

    // ---- state ----
    public static readonly List<DetailedBuilding> DetailedBuildings = new List<DetailedBuilding>();
    public static bool Built;
    public static string Report = "";
    public static int Hash;

    // ---- configuration ----
    const int DetailsPerBuildingMin = 4;            // minimum architectural details per building
    const int DetailsPerBuildingMax = 8;            // maximum architectural details per building (initial pass)
    const float MaxWallLengthWithoutDetail = 6.0f;  // Phase 5.4: no blank wall over about 6 m
    const float GapTolerance = 0.01f;

    // ---- main build ----
    /// <summary>Dependencies: BuildingSystem (buildings + openings), ArchitecturalKit (pieces).</summary>
    public static void Build()
    {
        if (!BuildingSystem.Built) BuildingSystem.Build();
        if (!ArchitecturalKit.Built) ArchitecturalKit.Build();

        Generate();
        Hash = ComputeHash();
        Built = true;
        Validate();
    }

    /// <summary>Clears detail data (including write-backs on buildings) and resets the build state.</summary>
    public static void Clear()
    {
        foreach (var b in BuildingSystem.Buildings)
            if (b != null && b.exterior != null && b.exterior.architecturalDetails != null)
                b.exterior.architecturalDetails.Clear();

        DetailedBuildings.Clear();
        Built = false;
        Report = "";
        Hash = 0;
    }

    // Pure generation step (no dependency builds, no validation). Safe to call repeatedly.
    static void Generate()
    {
        DetailedBuildings.Clear();

        var suitable = new List<ArchitecturalKit.ArchitecturalPiece>();
        foreach (var p in ArchitecturalKit.Pieces)
            if (!p.isTrim) suitable.Add(p);

        foreach (var building in BuildingSystem.Buildings)
        {
            var db = new DetailedBuilding { buildingId = building.id, details = new List<ExteriorDetail>() };
            building.exterior.architecturalDetails.Clear();

            // wall coverage lists (distance along each wall) used to break up long blank walls
            var coverage = new List<float>[4];
            for (int w = 0; w < 4; w++) coverage[w] = new List<float>();

            // 1. openings (doors + windows) generated by BuildingSystem
            foreach (var opening in building.exterior.openings)
            {
                db.details.Add(OpeningToDetail(building, opening));
                float s;
                int wall = BuildingSystem.NearestWall(building, opening.position, out s);
                coverage[wall].Add(s);
            }

            // 2. architectural pieces spread evenly around the walls
            if (suitable.Count > 0)
            {
                var pieces = SelectArchitecturalDetails(building, suitable);
                int n = pieces.Count;
                for (int i = 0; i < n; i++)
                {
                    int wall = i % 4;
                    int onWall = n / 4 + (wall < n % 4 ? 1 : 0);
                    int k = i / 4;
                    float s = BuildingSystem.WallLength(building, wall) * (k + 1) / (onWall + 1);
                    PlaceArchitectural(building, db, pieces[i], wall, s);
                    coverage[wall].Add(s);
                }

                // 3. fill any remaining blank stretch longer than the limit
                int extra = 0;
                for (int wall = 0; wall < 4; wall++)
                {
                    float len = BuildingSystem.WallLength(building, wall);
                    var pts = new List<float>(coverage[wall]);
                    pts.Add(0f);
                    pts.Add(len);
                    pts.Sort();
                    for (int i = 0; i < pts.Count - 1; i++)
                    {
                        float gap = pts[i + 1] - pts[i];
                        if (gap <= MaxWallLengthWithoutDetail) continue;
                        int inserts = Mathf.CeilToInt(gap / MaxWallLengthWithoutDetail) - 1;
                        for (int j = 1; j <= inserts; j++)
                        {
                            float s = pts[i] + gap * j / (inserts + 1);
                            var piece = suitable[(building.id * 31 + extra) % suitable.Count];
                            extra++;
                            PlaceArchitectural(building, db, piece, wall, s);
                        }
                    }
                }
            }

            // 4. decorative features (flower pots, lanterns, ...)
            foreach (var feature in GenerateDecorativeFeatures(building))
            {
                var placement = CalculateFeaturePlacement(building, feature);
                db.details.Add(new ExteriorDetail
                {
                    detailId = feature.id,
                    position = placement.position,
                    rotation = placement.rotation,
                    scale = placement.scale,
                    isArchitectural = false,
                    featureType = feature.type
                });
            }

            DetailedBuildings.Add(db);
        }
    }

    static int ComputeHash()
    {
        unchecked
        {
            int hs = (int)2166136261u;
            hs = (hs ^ DetailedBuildings.Count) * 16777619;
            foreach (var db in DetailedBuildings)
            {
                hs = (hs ^ db.buildingId) * 16777619;
                hs = (hs ^ db.details.Count) * 16777619;
                foreach (var d in db.details)
                {
                    hs = (hs ^ StableHash(d.detailId)) * 16777619;
                    hs = (hs ^ (int)(d.position.x * 100f)) * 16777619;
                    hs = (hs ^ (int)(d.position.y * 100f)) * 16777619;
                    hs = (hs ^ (int)(d.position.z * 100f)) * 16777619;
                    hs = (hs ^ (int)(d.rotation.eulerAngles.y * 10f)) * 16777619;
                    hs = (hs ^ (int)(d.scale.x * 100f)) * 16777619;
                    hs = (hs ^ (d.isArchitectural ? 1 : 0)) * 16777619;
                    hs = (hs ^ StableHash(d.featureType)) * 16777619;
                }
            }
            return hs;
        }
    }

    static int StableHash(string s)
    {
        unchecked
        {
            int h = (int)2166136261u;
            if (s == null) return h;
            for (int i = 0; i < s.Length; i++) h = (h ^ s[i]) * 16777619;
            return h;
        }
    }

    // ---- validation ----
    /// <summary>Validates the exterior detailing against the Phase 5.4 requirements.</summary>
    public static string Validate()
    {
        if (!Built)
        {
            Build(); // Build() runs Validate() itself and fills Report
            return Report;
        }

        var sb = new StringBuilder("[ExteriorDetailSystem 5.4]\n");
        var fails = new List<string>();
        int pass = 0;

        int totalBuildings = DetailedBuildings.Count;
        int insufficient = 0;
        int longBlankWalls = 0;
        int habitableWithoutWindows = 0;

        foreach (var db in DetailedBuildings)
        {
            var building = BuildingSystem.Buildings[db.buildingId];

            // minimum architectural details
            int architecturalCount = 0;
            foreach (var d in db.details)
                if (d.isArchitectural) architecturalCount++;
            if (architecturalCount < DetailsPerBuildingMin)
                insufficient++;

            // no blank wall stretch longer than the limit (openings + architectural pieces break up a wall)
            var coverage = new List<float>[4];
            for (int w = 0; w < 4; w++) coverage[w] = new List<float>();
            foreach (var d in db.details)
            {
                if (!d.isArchitectural && d.featureType != "window" && d.featureType != "door") continue;
                Vector2 local = BuildingSystem.WorldToLocal(building, d.position.x, d.position.z);
                float s;
                int wall = BuildingSystem.NearestWall(building, local, out s);
                coverage[wall].Add(s);
            }
            bool longWall = false;
            for (int wall = 0; wall < 4 && !longWall; wall++)
            {
                var pts = new List<float>(coverage[wall]);
                pts.Add(0f);
                pts.Add(BuildingSystem.WallLength(building, wall));
                pts.Sort();
                for (int i = 0; i < pts.Count - 1; i++)
                {
                    if (pts[i + 1] - pts[i] > MaxWallLengthWithoutDetail + GapTolerance) { longWall = true; break; }
                }
            }
            if (longWall) longBlankWalls++;

            // every habitable room needs a window
            foreach (var floor in building.floorPlan)
            {
                foreach (var room in floor.rooms)
                {
                    bool habitable = room.roomType == "living" || room.roomType == "kitchen" || room.roomType == "bedroom";
                    if (habitable && room.windowCount <= 0)
                        habitableWithoutWindows++;
                }
            }
        }

        if (insufficient == 0) pass++;
        else fails.Add(insufficient + " buildings have insufficient architectural details (<" + DetailsPerBuildingMin + ")");

        if (longBlankWalls == 0) pass++;
        else fails.Add(longBlankWalls + " buildings have wall stretches longer than " + MaxWallLengthWithoutDetail + "m without detail");

        if (habitableWithoutWindows == 0) pass++;
        else fails.Add(habitableWithoutWindows + " habitable rooms lack windows");

        // determinism: regenerate from the same inputs and compare hashes
        int hash1 = Hash;
        Generate();
        int hash2 = ComputeHash();
        if (hash1 == hash2) pass++;
        else fails.Add("exterior detailing generation is not deterministic");

        sb.AppendLine("buildings detailed: " + totalBuildings);
        sb.AppendLine("buildings with insufficient details: " + insufficient + "/" + totalBuildings);
        sb.AppendLine("buildings with long blank walls: " + longBlankWalls + "/" + totalBuildings);
        sb.AppendLine("habitable rooms without windows: " + habitableWithoutWindows);
        sb.AppendLine("RULES (5.4): " + pass + " pass / " + fails.Count + " fail");
        foreach (var f in fails) sb.AppendLine("  FAIL: " + f);
        Report = sb.ToString();
        return Report;
    }

    // ---- helpers ----

    static ExteriorDetail OpeningToDetail(BuildingSystem.Building b, BuildingSystem.Opening o)
    {
        float s;
        int wall = BuildingSystem.NearestWall(b, o.position, out s);
        bool isDoor = o.type == BuildingSystem.Opening.OpeningType.Door;
        return new ExteriorDetail
        {
            detailId = isDoor ? "door" : "window",
            position = BuildingSystem.LocalToWorld(b, BuildingSystem.PointOnWall(b, wall, s), o.baseHeight),
            rotation = Quaternion.Euler(0f, b.yaw * Mathf.Rad2Deg + BuildingSystem.WallYawDeg(wall), 0f),
            scale = new Vector3(o.size.x, o.size.y, o.revealDepth),
            isArchitectural = false,
            featureType = o.type.ToString().ToLower()
        };
    }

    static void PlaceArchitectural(BuildingSystem.Building b, DetailedBuilding db, ArchitecturalKit.ArchitecturalPiece piece, int wall, float s)
    {
        db.details.Add(new ExteriorDetail
        {
            detailId = piece.id,
            position = BuildingSystem.LocalToWorld(b, BuildingSystem.PointOnWall(b, wall, s), 0f),
            rotation = Quaternion.Euler(0f, b.yaw * Mathf.Rad2Deg + BuildingSystem.WallYawDeg(wall), 0f),
            scale = piece.size,
            isArchitectural = true,
            featureType = ""
        });
        b.exterior.architecturalDetails.Add(new BuildingSystem.Building.ArchitecturalDetail
        {
            id = piece.id,
            type = piece.type,
            style = piece.style
        });
    }

    /// <summary>Selects a deterministic subset of kit pieces for a building (seeded by building id).</summary>
    static List<ArchitecturalKit.ArchitecturalPiece> SelectArchitecturalDetails(
        BuildingSystem.Building building, List<ArchitecturalKit.ArchitecturalPiece> suitable)
    {
        int count = Mathf.Min(DetailsPerBuildingMax, Mathf.Max(DetailsPerBuildingMin, suitable.Count / 2));
        count = Mathf.Min(count, suitable.Count);

        var selected = new List<ArchitecturalKit.ArchitecturalPiece>();
        var rand = new System.Random(building.id * 1337 + 5);
        var indices = new HashSet<int>();
        while (selected.Count < count && indices.Count < suitable.Count)
        {
            int idx = rand.Next(suitable.Count);
            if (indices.Add(idx))
                selected.Add(suitable[idx]);
        }
        return selected;
    }

    // ---- decorative features ----
    class DecorativeFeature
    {
        public string type; // e.g., "flowerPot", "lantern"
        public string id;   // deterministic: type_buildingId_index
    }

    static List<DecorativeFeature> GenerateDecorativeFeatures(BuildingSystem.Building building)
    {
        var features = new List<DecorativeFeature>();
        var rand = new System.Random(building.id * 999 + 7);

        // roll every random value up front so the sequence never depends on building flags
        bool flowerPots = rand.NextDouble() > 0.3;   // 70%
        bool laundryLine = rand.NextDouble() > 0.2;  // 80%
        bool hangingHerbs = rand.NextDouble() > 0.4; // 60%
        bool dovecote = rand.NextDouble() > 0.7;     // 30%

        int idx = 0;
        Action<string> add = type => features.Add(new DecorativeFeature { type = type, id = type + "_" + building.id + "_" + (idx++) });

        if (flowerPots) add("flowerPot");
        if (building.exterior.hasLanterns) add("lantern");
        if (laundryLine) add("laundryLine");
        if (building.exterior.hasWoodStacks) add("woodStack");
        if (building.exterior.hasBarrels) add("barrel");
        if (hangingHerbs) add("hangingHerbs");
        if (building.exterior.hasShopSign) add("shopSign");
        if (building.floors >= 2 && dovecote) add("dovecote");

        return features;
    }

    /// <summary>Places a feature just outside one of the building's walls.</summary>
    static (Vector3 position, Quaternion rotation, Vector3 scale) CalculateFeaturePlacement(
        BuildingSystem.Building building, DecorativeFeature feature)
    {
        var rand = new System.Random(building.id * 123 + StableHash(feature.type));
        int wall = rand.Next(4);
        float len = BuildingSystem.WallLength(building, wall);
        float s = len * (0.15f + 0.7f * (float)rand.NextDouble());
        Vector2 local = BuildingSystem.PointOnWall(building, wall, s) + BuildingSystem.WallNormal(wall) * 0.6f;

        Vector3 scale = Vector3.one;
        float height = 0f;
        switch (feature.type)
        {
            case "flowerPot":    scale = new Vector3(0.3f, 0.5f, 0.3f); break;
            case "lantern":      scale = new Vector3(0.2f, 0.4f, 0.2f); height = 1.5f; break;
            case "laundryLine":  scale = new Vector3(2.0f, 0.1f, 2.0f); height = 2.0f; break;
            case "woodStack":    scale = new Vector3(1.0f, 1.0f, 1.0f); break;
            case "barrel":       scale = new Vector3(0.5f, 0.8f, 0.5f); break;
            case "hangingHerbs": scale = new Vector3(0.2f, 0.2f, 0.2f); height = 2.0f; break;
            case "shopSign":     scale = new Vector3(1.0f, 0.2f, 0.1f); height = 2.5f; break;
            case "dovecote":     scale = new Vector3(0.8f, 0.8f, 0.8f); height = BuildingSystem.FloorHeight * building.floors; break;
        }

        Vector3 pos = BuildingSystem.LocalToWorld(building, local, height);
        Quaternion rot = Quaternion.Euler(0f, building.yaw * Mathf.Rad2Deg + BuildingSystem.WallYawDeg(wall), 0f);
        return (pos, rot, scale);
    }

#if UNITY_EDITOR
    [UnityEditor.MenuItem("Island/Phase 5.4 Exterior Detailing + Validate")]
    static void Menu()
    {
        Built = false;
        Build();
        Debug.Log(Report);
    }
#endif
}
